import java.util.Arrays;

class Solution {
    public int[][] allCellsDistOrder(int rows, int cols, int rCenter, int cCenter) {
        int[][] cells = new int[rows * cols][2];
        int index = 0;
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                cells[index++] = new int[]{row, col};
            }
        }
        Arrays.sort(cells, (a, b) -> {
            int distanceA = distance(a[0], a[1], rCenter, cCenter);
            int distanceB = distance(b[0], b[1], rCenter, cCenter);
            if (distanceA != distanceB) {
                return Integer.compare(distanceA, distanceB);
            }
            if (a[0] != b[0]) {
                return Integer.compare(a[0], b[0]);
            }
            return Integer.compare(a[1], b[1]);
        });
        return cells;
    }

    private int distance(int row, int col, int rCenter, int cCenter) {
        return Math.abs(row - rCenter) + Math.abs(col - cCenter);
    }
}

import java.util.ArrayDeque;
import java.util.Queue;

class Solution {
    public int[][] allCellsDistOrder(int rows, int cols, int rCenter, int cCenter) {
        int[][] result = new int[rows * cols][2];
        boolean[][] visited = new boolean[rows][cols];
        Queue<int[]> queue = new ArrayDeque<>();
        queue.offer(new int[]{rCenter, cCenter});
        visited[rCenter][cCenter] = true;

        int index = 0;
        int[] rowDelta = {-1, 0, 0, 1};
        int[] colDelta = {0, -1, 1, 0};
        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            result[index++] = cell;
            for (int direction = 0; direction < 4; direction++) {
                int nextRow = cell[0] + rowDelta[direction];
                int nextCol = cell[1] + colDelta[direction];
                if (nextRow >= 0 && nextRow < rows && nextCol >= 0 && nextCol < cols
                        && !visited[nextRow][nextCol]) {
                    visited[nextRow][nextCol] = true;
                    queue.offer(new int[]{nextRow, nextCol});
                }
            }
        }
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    public int[][] allCellsDistOrder(int rows, int cols, int rCenter, int cCenter) {
        int maxDistance = rows + cols - 2;
        List<List<int[]>> buckets = new ArrayList<>();
        for (int distance = 0; distance <= maxDistance; distance++) {
            buckets.add(new ArrayList<>());
        }
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int distance = Math.abs(row - rCenter) + Math.abs(col - cCenter);
                buckets.get(distance).add(new int[]{row, col});
            }
        }

        int[][] result = new int[rows * cols][2];
        int index = 0;
        for (List<int[]> bucket : buckets) {
            for (int[] cell : bucket) {
                result[index++] = cell;
            }
        }
        return result;
    }
}

class Solution {
    public int[][] allCellsDistOrder(int rows, int cols, int rCenter, int cCenter) {
        int maxDistance = rows + cols - 2;
        int[] counts = new int[maxDistance + 1];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int distance = Math.abs(row - rCenter) + Math.abs(col - cCenter);
                counts[distance]++;
            }
        }

        int[] start = new int[maxDistance + 1];
        for (int distance = 1; distance <= maxDistance; distance++) {
            start[distance] = start[distance - 1] + counts[distance - 1];
        }
        int[] next = start.clone();
        int[][] result = new int[rows * cols][2];
        for (int row = 0; row < rows; row++) {
            for (int col = 0; col < cols; col++) {
                int distance = Math.abs(row - rCenter) + Math.abs(col - cCenter);
                result[next[distance]++] = new int[]{row, col};
            }
        }
        return result;
    }
}

class Solution {
    public int[][] allCellsDistOrder(int rows, int cols, int rCenter, int cCenter) {
        int[][] result = new int[rows * cols][2];
        int index = 0;
        int maxDistance = rows + cols - 2;

        for (int distance = 0; distance <= maxDistance; distance++) {
            for (int rowOffset = -distance; rowOffset <= distance; rowOffset++) {
                int row = rCenter + rowOffset;
                if (row < 0 || row >= rows) {
                    continue;
                }
                int colOffset = distance - Math.abs(rowOffset);
                int leftCol = cCenter - colOffset;
                int rightCol = cCenter + colOffset;
                if (leftCol >= 0 && leftCol < cols) {
                    result[index++] = new int[]{row, leftCol};
                }
                if (colOffset != 0 && rightCol >= 0 && rightCol < cols) {
                    result[index++] = new int[]{row, rightCol};
                }
            }
        }
        return result;
    }
}
